const Icon *find_icon(const char *name)
{
    for (const Icon &i : kIcons)
        if (strcmp(i.name, name) == 0)
            return &i;
    return nullptr;
}

const Icon *icons_begin() { return kIcons; }
const Icon *icons_end() { return kIcons + sizeof kIcons / sizeof kIcons[0]; }

